import sys
import os
import argparse
import traceback

def parse_args():
    parser = argparse.ArgumentParser(description='Iterative RPE reconstruction with SIRF.')
    parser.add_argument('--raw-data-file', type=str, default=None, help='Raw k-space data file (HDF5).')
    parser.add_argument('--data-path', type=str, default=None, help='Path to data files.')
    parser.add_argument('--output-file', type=str, default='simulated_data.h5', help='Output file for simulated data.')
    parser.add_argument('--engine', type=str, default='Gadgetron', choices=['Gadgetron', 'GadgetronNonCartesian', 'Parallelproj'], help='Reconstruction engine.')
    parser.add_argument('--run-recon', action='store_true', help='Run reconstruction if non-cartesian code was compiled.')
    parser.add_argument('--trajectory', type=str, default='radial', choices=['cartesian', 'radial', 'goldenangle', 'grpe'], help='Trajectory type.')
    parser.add_argument('--show-plots', action='store_true', help='Show plots.')
    return parser.parse_args()

def import_engine(engine):
    if engine == 'Gadgetron':
        import sirf.Gadgetron as eng
    elif engine == 'GadgetronNonCartesian':
        import sirf.GadgetronNonCartesian as eng
    elif engine == 'Parallelproj':
        import sirf.Parallelproj as eng
    else:
        raise ValueError(f"Unknown engine: {engine}")
    return eng

def cg_reconstruction(acq_data, eng, niter=10, show_plots=False):
    # Compute coil sensitivity maps
    csm = eng.CoilSensitivityData()
    csm.calculate(acq_data)
    # Set up acquisition model
    acq_model = eng.AcquisitionModel()
    acq_model.set_coil_sensitivity_maps(csm)
    acq_model.set_acquisition_data(acq_data)
    # Backward projection (adjoint)
    initial_image = acq_model.backward(acq_data)
    # Define symmetric operator for CG
    class SymmetricOperator:
        def __init__(self, acq_model):
            self.acq_model = acq_model
        def apply(self, x):
            return self.acq_model.backward(self.acq_model.forward(x))
    sym_op = SymmetricOperator(acq_model)
    # CG iterations
    x = initial_image.clone()
    b = initial_image.clone()
    r = b.clone()
    r -= sym_op.apply(x)
    p = r.clone()
    rsold = r.dot(r)
    for i in range(niter):
        Ap = sym_op.apply(p)
        alpha = rsold / (p.dot(Ap) + 1e-10)
        x += p * alpha
        r -= Ap * alpha
        rsnew = r.dot(r)
        if show_plots:
            try:
                x.show(title=f'CG Iter {i+1}')
            except Exception:
                pass
        if rsnew < 1e-6:
            break
        p = r + p * (rsnew / (rsold + 1e-10))
        rsold = rsnew
    return x

def main():
    try:
        args = parse_args()
        eng = import_engine(args.engine)
        # Locate raw data file
        if args.raw_data_file:
            raw_data_file = args.raw_data_file
        else:
            if args.data_path:
                files = [f for f in os.listdir(args.data_path) if f.endswith('.h5') or f.endswith('.hdf5')]
                if not files:
                    raise FileNotFoundError("No HDF5 files found in data path.")
                raw_data_file = os.path.join(args.data_path, files[0])
            else:
                raise ValueError("Either --raw-data-file or --data-path must be specified.")
        # Read acquisition data
        acq_data = eng.AcquisitionData(raw_data_file)
        # Pre-process acquisition data
        proc = eng.AcquisitionDataProcessor()
        proc.preprocess_acquisition_data(acq_data)
        # Set trajectory
        if args.trajectory == 'cartesian':
            acq_data.set_data_trajectory('cartesian')
        elif args.trajectory == 'radial':
            acq_data.set_data_trajectory('radial')
        elif args.trajectory == 'goldenangle':
            acq_data.set_data_trajectory('goldenangle')
        elif args.trajectory == 'grpe':
            acq_data.set_data_trajectory('grpe')
        else:
            raise ValueError(f"Unknown trajectory type: {args.trajectory}")
        # Sort processed acquisition data
        acq_data.sort()
        # Perform reconstruction if requested
        if args.run_recon:
            recon_image = cg_reconstruction(acq_data, eng, niter=10, show_plots=args.show_plots)
            recon_image.write(args.output_file)
            if args.show_plots:
                try:
                    recon_image.show(title='Reconstructed Image')
                except Exception:
                    pass
        else:
            print("Reconstruction not run. Use --run-recon to perform reconstruction.")
    except Exception as e:
        print("Error during execution:")
        print(str(e))
        traceback.print_exc()

if __name__ == '__main__':
    main()
